import{_ as l,l as o,o as e,c as s,v as r,p as B,x as t,d as n,i as d,S as v}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"BBRv2 / v3","description":"","frontmatter":{"title":"BBRv2 / v3","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bbr-v2-v3.md","filePath":"cs/bbr-v2-v3.md","lastUpdated":1789023840000}'),p={name:"cs/bbr-v2-v3.md"};function c(C,a,h,b,m,_){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="bbrv2-v3" tabindex="-1">BBRv2 / v3 <a class="header-anchor" href="#bbrv2-v3" aria-label="Permalink to &quot;BBRv2 / v3&quot;">​</a></h1><div class="epigraph"><p>BBR 用带宽与 RTT 估计管道，不靠丢包减半；v2/v3 修过估、公平与 ECN 反应，仍在模型与测量之间摇摆。</p><footer>—— 据 Cardwell et al., BBR, ACM Queue 2016；BBRv2/v3 公开设计说明整理</footer></div><p>主干<a href="/cs/bbr">BBR 对照</a> 已给 v1 直觉。<a href="/cs/bufferbloat">缓冲膨胀</a> 是 v1 在深缓冲上的痛。<a href="/cs/quic-migration">上一课</a> 不改控制律。缺口是 <strong>v2/v3 补什么</strong>：带宽过估、与 CUBIC 共存、ECN。本课不把 Vegas 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>v1 ProbeBw 可把队列推高，深缓冲上仍膨胀；对 CUBIC 不公平。v2：更保守的带宽头、对丢失/ECN 作出反应、量化公平。v3 继续调探测与启动。模型：maxBW × minRTT ≈ BDP，窗口绕此值。误码链路把丢当拥塞仍可能，但比 AIMD 少抽空——卫星动机还在。</p><p>不要把版本号写成已在 RFC 终稿冻结；课钉对象与问题。</p><p><span class="marginnote">v1：Cardwell 2016。后续版本以公开幻灯与代码为准，不把未冻结的草案号当标准。</span></p><h3 id="模型不是-aimd-换皮" tabindex="-1">模型不是 AIMD 换皮 <a class="header-anchor" href="#模型不是-aimd-换皮" aria-label="Permalink to &quot;模型不是 AIMD 换皮&quot;">​</a></h3><p>v1 在深缓冲仍可膨胀。v2/v3 更听丢与 ECN，并修公平。版本以公开设计说明与代码为准，课钉对象不钉某年冻结稿。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 AIMD 相位图 vs BBR 管道估计。画：Probe → Drain → Cruise。与 DCTCP：都利用 ECN，一个比例减，一个进模型。</p>',11)),(e(),B(v,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BW%5B%22%E4%BC%B0%E8%AE%A1%E5%B8%A6%E5%AE%BD%22%5D%20--%3E%20BDP%5B%22%E4%B9%98%20minRTT%22%5D%0A%20%20BDP%20--%3E%20CAP%5B%22%E5%B7%A1%E8%88%AA%E7%AA%97%E5%8F%A3%22%5D%0A%20%20SIG%5B%22%E4%B8%A2%2FECN%22%5D%20--%3E%20V2%5B%22v2%20%E6%9B%B4%E5%90%AC%E4%BF%A1%E5%8F%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>QUIC 与 Linux TCP 都有实现。多路径下每条路径一套估计。AQM 浅队列让 minRTT 更真。P4 不实现 BBR，BBR 在端。RoCE 用 DCQCN 不是 BBR。</p><p>过估：把突发当可用带宽，会伤同队列邻居——v2 要压这点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 PCC 等学习型 CC 全文。延迟型 Vegas/Swift 是下一课。后课默认：BBR 族是基于模型的 CC；v2/v3 针对公平与膨胀补丁。</p><p>与不可 ECN 的公网 CUBIC 混跑，结果仍依赖缓冲。</p><p>上一课留下的缺口在本课收口；「BBRv2 / v3」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/delay-based-cc">延迟型拥塞 Vegas / Swift</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BBR 用 BW 与 RTT 估 BDP，而非纯 AIMD。</li><li>v2/v3 加强对丢/ECN 与公平的反应。</li><li>深缓冲与误码仍是模型边界。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Cardwell et al., 2016；BBRv2/v3 说明。</li></ul>',10))])}const u=l(p,[["render",c]]);export{E as __pageData,u as default};
